import { AppError } from './errors';
export function imagePath(value: string): string {
  if (!/^\/api\/v1\/(?:manga\/\d+\/thumbnail|extension\/icon\/[A-Za-z0-9_.-]+)$/.test(value))
    throw new AppError('VALIDATION_ERROR', 'Unsupported image path');
  return value;
}
export function proxyImage(value: string | null): string | null {
  return value ? `/api/suwayomi/image?path=${encodeURIComponent(imagePath(value))}` : null;
}

/** Only root-relative image routes generated by Bunko; never normalize an attacker path. */
export function localImageUrl(value: string): boolean {
  if (!value.startsWith('/api/') || /[\\#\s]/.test(value)) return false;
  try {
    const url = new URL(value, 'http://bunko.invalid');
    if (url.origin !== 'http://bunko.invalid' || !value.startsWith(url.pathname + '?'))
      return false;
    const keys = [...url.searchParams.keys()];
    if (url.pathname === '/api/kavita/image')
      return (
        keys.length === 1 &&
        keys[0] === 'seriesId' &&
        /^[1-9]\d*$/.test(url.searchParams.get('seriesId')!) &&
        Number(url.searchParams.get('seriesId')) <= 2147483647
      );
    if (/^\/api\/covers\/[1-9]\d*$/.test(url.pathname))
      return (
        Number(url.pathname.split('/').at(-1)) <= 2147483647 &&
        keys.length === 1 &&
        keys[0] === 'v' &&
        /^[a-f0-9]{16}$/.test(url.searchParams.get('v')!)
      );
    if (url.pathname === '/api/suwayomi/image' && keys.length === 1 && keys[0] === 'path') {
      imagePath(url.searchParams.get('path')!);
      return true;
    }
  } catch {
    /* Unrecognized image paths never reach an upstream. */
  }
  return false;
}
